const MAX_COUNT:usize=64;
fn lowerAscii(c:i64)i64{return if(c>=65 and c<=90)c+32 else c;}
fn less(v:[*]const i64,o:*const [64]usize,l:*const [64]usize,p:*const [64]usize,a:usize,b:usize)bool{const lim=@min(p[a],p[b]);for(0..lim)|i|{const x=lowerAscii(v[o[a]+i]);const y=lowerAscii(v[o[b]+i]);if(x!=y)return x<y;}if(p[a]!=p[b])return p[a]<p[b];const sa=l[a]-p[a];const sb=l[b]-p[b];if(sa==0 or sb==0)return sa<sb;var za:usize=0;var zb:usize=0;while(za<sa and v[o[a]+p[a]+za]==48):(za+=1){}while(zb<sb and v[o[b]+p[b]+zb]==48):(zb+=1){}const na=sa-za;const nb=sb-zb;if(na!=nb)return na<nb;for(0..na)|i|{const x=v[o[a]+p[a]+za+i];const y=v[o[b]+p[b]+zb+i];if(x!=y)return x<y;}return false;}
export fn natural_sort(v:[*]const i64,n:usize,out:[*]u8,cap:usize)i64{if(n<1 or n>4161 or v[0]<0 or v[0]>64)return -1;const count:usize=@intCast(v[0]);var offs:[64]usize=@splat(0);var lens:[64]usize=@splat(0);var pres:[64]usize=@splat(0);var order:[64]usize=@splat(0);var cursor:usize=1;var total:usize=0;for(0..count)|i|{if(cursor>=n or v[cursor]<0 or v[cursor]>64)return -1;lens[i]=@intCast(v[cursor]);cursor+=1;offs[i]=cursor;pres[i]=lens[i];var digit=false;for(0..lens[i])|j|{const c=v[cursor+j];if(c>=48 and c<=57){if(j==0)return -1;if(!digit){pres[i]=j;digit=true;}}else if(!((c>=65 and c<=90)or(c>=97 and c<=122))or digit)return -1;}cursor+=lens[i];total+=lens[i];order[i]=i;}if(cursor!=n)return -1;for(1..count)|i|{const item=order[i];var j=i;while(j>0 and less(v,&offs,&lens,&pres,item,order[j-1])):(j-=1){order[j]=order[j-1];}order[j]=item;}const bytes=total+(if(count>0)count-1 else 0);if(bytes>cap)return -2;var w:usize=0;for(0..count)|i|{if(i>0){out[w]=10;w+=1;}const k=order[i];for(0..lens[k])|j|{out[w]=@intCast(v[offs[k]+j]);w+=1;}}return @intCast(w);}
